def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    emit(out, "Start from the input; every shape stays in place, only colours may change.")
    for o in objects(g, bg=bg):
        if o["size"] <= 2:
            for y, x in o["cells"]:
                out[y, x] = 3
            emit(out, f"Object of colour {o['colour']} has only {o['size']} cell(s), so it is painted 3; larger shapes are kept.")
    emit(out, "All objects of size 1 or 2 are now green; objects of size 3 or more are unchanged.")
    return out
